PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE Acciones(id_accion INTEGER PRIMARY KEY, titulo TEXT NOT NULL, descripcion TEXT NOT NULL, categoria TEXT NOT NULL, dificultad TEXT NOT NULL CHECK(dificultad IN ('Baja','Media')), id_contenido INTEGER NOT NULL REFERENCES Contenidos(id_contenido));
CREATE TABLE ContenidoFuente(id_contenido INTEGER NOT NULL REFERENCES Contenidos(id_contenido), id_fuente INTEGER NOT NULL REFERENCES Fuentes(id_fuente), PRIMARY KEY(id_contenido,id_fuente));
CREATE TABLE Contenidos(id_contenido INTEGER PRIMARY KEY, titulo TEXT NOT NULL CHECK(length(trim(titulo))>0), texto TEXT NOT NULL, seccion TEXT NOT NULL, fecha_actualizacion TEXT NOT NULL, id_tipo INTEGER REFERENCES TiposEnergia(id_tipo));
CREATE TABLE Fuentes(id_fuente INTEGER PRIMARY KEY, organismo TEXT NOT NULL, titulo TEXT NOT NULL, url TEXT NOT NULL UNIQUE, fecha_consulta TEXT NOT NULL);
CREATE TABLE TiposEnergia(id_tipo INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, descripcion TEXT NOT NULL, recurso_principal TEXT NOT NULL);
COMMIT;
PRAGMA foreign_keys = ON;
PRAGMA foreign_key_check;
